      ACCEPT_TOKEN(sym_comment);
      END_STATE();
    case 64:
      ACCEPT_TOKEN(sym_comment);
      if (lookahead == '\n') ADVANCE(55);
      if (lookahead == '"') ADVANCE(65);
      if (lookahead == '{') ADVANCE(66);
      if (lookahead != 0) ADVANCE(50);
      END_STATE();
    case 65:
      ACCEPT_TOKEN(sym_comment);
      if (lookahead == '\n') ADVANCE(55);
      if (lookahead == '"' ||
          lookahead == '{') ADVANCE(66);
      if (lookahead != 0) ADVANCE(50);
      END_STATE();
    case 66:
      ACCEPT_TOKEN(sym_comment);
      if (lookahead != 0 &&
          lookahead != '\n') ADVANCE(66);
      END_STATE();
    default:
      return false;
